  const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
  const skin=new THREE.MeshStandardMaterial({color:[0x777a67,0x827464,0x62685f,0x867b6d][Math.floor(Math.random()*4)],roughness:.95});
  const coat=new THREE.MeshStandardMaterial({color:[0x393a35,0x514139,0x373d40,0x524e3d][Math.floor(Math.random()*4)],roughness:.9});
  const body=box(g,.55,.83,.3,coat,0,1.05,0,true);body.rotation.x=(Math.random()-.5)*.12;
  const head=new THREE.Mesh(new THREE.SphereGeometry(.23,12,10),skin);head.position.set((Math.random()-.5)*.06,1.65,-.035);head.castShadow=true;g.add(head);
  const jaw=box(g,.25,.11,.21,skin,0,1.48,-.02,true);jaw.rotation.x=-.16;
  for(let s of [-1,1]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.035,7,6),mats.eye);eye.position.set(s*.085,1.68,-.235);g.add(eye);
   const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.085,.56,4,8),skin);arm.position.set(s*.39,1.03,-.01);arm.rotation.z=s*.48;arm.castShadow=true;g.add(arm);
   const hand=new THREE.Mesh(new THREE.SphereGeometry(.09,8,6),skin);hand.position.set(s*.59,.78,-.03);g.add(hand);
   const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.105,.47,4,8),coat);leg.position.set(s*.16,.39,0);g.add(leg);
  }
  // Torn shoulder strap, dried blood streaks, and uneven posture.
  const strap=box(g,.09,.72,.035,mats.dark,-.16,1.1,-.17);strap.rotation.z=-.42;
  for(let j=0;j<3;j++){const smear=box(g,.035,.18+Math.random()*.15,.012,mats.blood,(Math.random()-.5)*.3,1.35-Math.random()*.36,-.166);smear.rotation.z=(Math.random()-.5)*.5;}
  g.userData={hp:1,phase:Math.random()*6,hit:0,attack:0,speed:.7+Math.random()*.22};zombies.push(g);return g;
}

